const fs = require('fs');
const content = fs.readFileSync('.env.test', 'utf8');
const lines = content.split('\n').filter(line => line.trim() && !line.startsWith('#'));
const result = {};
lines.forEach(line => {
  const [key, ...valueParts] = line.split('=');
  result[key] = valueParts.join('=');
});
console.log(JSON.stringify(result));

